import React, {useEffect, useState} from "react";
import {AuthService} from "../../services/AuthApi";
import LoginLayout from "../../components/LoginLayout/LoginLayout";
import {useNavigate} from "react-router-dom";

export default function SignIn() {
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        async () => {
            AuthService.myInfo()
                .then(response => response.data)
        };

        checkLogin().catch(err => {
            console.log("Unhandled error in checkLogin:", err.response ? err.response.data : err);
        });
    }, [navigate]);

    // async function xử lý submit
    async function handleSignIn(user) {
        setLoading(true);
        setError("");

        try {
            await AuthService.signIn(user.username, user.password);
            navigate("/admin/dashboard");
        } catch (err) {
            alert(err.response.data);
        } finally {
            setLoading(false);
        }
    }

    return (
        <LoginLayout
            title="Sign In"
            handleOnSubmit={handleSignIn}
            linkHref="/signup"
            submitText="Sign In"
            label="Sign up"
            flag={true}
            linkHref2="/forgetpassword"
            label2="Forget Password"
            error={error}       // truyền lỗi cho LoginLayout hiển thị
            loading={loading}   // truyền loading nếu muốn hiển thị spinner
        />
    );
}
